import { useState, useEffect } from 'react';
import { Arrow } from './icons.jsx';
import { loadBlogPosts, formatBlogDate, estimateReadTime } from '../../../utils/blogPosts';

const FALLBACK_POSTS = [
  {
    slug: 'why-your-h1-doesnt-matter',
    category: 'Field notes',
    date: '2026-05-19',
    title: "Why your H1 doesn't matter to ChatGPT anymore",
    excerpt: 'After auditing 4,200 sites we learned that paragraph two, not the headline, decides whether you\'re cited.',
    body: '',
  },
  {
    slug: '2026-aeo-benchmark-report-q1',
    category: 'Benchmarks',
    date: '2026-05-11',
    title: 'The 2026 AEO benchmark report (Q1)',
    excerpt: 'Average visibility across SaaS, DTC and fintech, and which schema patterns moved the needle.',
    body: '',
  },
  {
    slug: 'prompt-clustering-for-buyer-intent',
    category: 'Tactics',
    date: '2026-04-29',
    title: 'Prompt clustering for buyer intent, the right way',
    excerpt: 'Stop ranking for adjectives. Start ranking for the actual sentence your buyer types into the box.',
    body: '',
  },
];

export default function Blog() {
  const [posts, setPosts] = useState(FALLBACK_POSTS);

  useEffect(() => {
    loadBlogPosts()
      .then(all => setPosts(all.slice(0, 3))) // most recent 3, for the landing page teaser
      .catch(() => {}); // keep the bundled fallback visible if a post asset cannot load
  }, []);

  return (
    <section className="section" id="blog">
      <div className="section-head">
        <div className="section-eyebrow"><span className="mono">08</span><span>From the journal</span></div>
        <h2 className="section-title">What's happening at <em>aeo-app.</em></h2>
      </div>
      <div className="posts">
        {posts.map((p, i) => (
          <a className="post" href={`/blog/${p.slug}`} key={p.slug}>
            {p.featured_image ? (
              <img className="post-thumb" src={p.featured_image} alt="" style={{ objectFit: 'cover', width: '100%', height: '100%' }} />
            ) : (
              <div className="post-thumb" data-i={i % 3} />
            )}
            <div className="post-body">
              <div className="post-meta">
                <span>{p.category}</span><span>·</span><span>{formatBlogDate(p.date)}</span><span>·</span><span>{estimateReadTime(p.body)}</span>
              </div>
              <h3 className="post-title">{p.title}</h3>
              <p className="post-ex">{p.excerpt}</p>
              <span className="post-read">Read article <Arrow size={12} /></span>
            </div>
          </a>
        ))}
      </div>
    </section>
  );
}
